import {geometry,esc} from './plan-core.js';
export function assessmentSvg(c){let lines='';for(const b of c.boundaryAssessment.boundaries){for(const s of b.segments){const color=c.boundaryAssessment.legend[s.classification],dx=s.b[0]-s.a[0],dz=s.b[1]-s.a[1],len=Math.hypot(dx,dz),offset=s.component==='하부벽 가정'?-90:s.component==='상부벽 가정'?90:0,normal=[-dz/len,dx/len];const a=s.a.map((v,i)=>v+normal[i]*offset),end=s.b.map((v,i)=>v+normal[i]*offset);lines+=`<line x1="${a[0]}" y1="${a[1]}" x2="${end[0]}" y2="${end[1]}" stroke="${color}" stroke-width="${offset?28:65}" ${offset?'stroke-dasharray="60 45"':''}><title>${esc(b.name+' / '+s.component+' / '+s.classification+' / '+s.evidence)}</title></line>`;}}return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="-700 -400 9350 12200" role="img" aria-label="발코니 경계 segment 확장 판정도"><rect x="-700" y="-400" width="9350" height="12200" fill="white"/><g opacity=".25">${geometry(c,{roomNames:false})}</g>${lines}${c.rooms.map(r=>`<text x="${r.labelPosition[0]}" y="${r.labelPosition[1]}" text-anchor="middle" font-family="sans-serif" font-size="220" fill="#243746">${esc(r.name)}</text>`).join('')}</svg>`;}
